package com.booksyde.service; import com.booksyde.dto.request.CreateVolumeRequest; import com.booksyde.dto.response.VolumeResponse; import com.booksyde.entity.VolumeEntity; import com.booksyde.exception.ResourceNotFoundException; import com.booksyde.mapper.VolumeMapper; import com.booksyde.repository.VolumeRepository; import com.booksyde.security.BooksydeRole; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class VolumeService {private final VolumeRepository repo; private final BookService books; public VolumeService(VolumeRepository repo,BookService books){this.repo=repo;this.books=books;} @Transactional(readOnly=true) public List<VolumeResponse> list(UUID mangaId,UUID userId,Set<BooksydeRole> roles){books.find(mangaId,userId,roles); return repo.findAllByMangaIdOrderByNumberAsc(mangaId).stream().map(VolumeMapper::toResponse).toList();} @Transactional public VolumeResponse create(UUID mangaId,CreateVolumeRequest r,UUID userId,Set<BooksydeRole> roles){var manga=books.get(mangaId); books.ensureOwner(manga,userId,roles); var e=new VolumeEntity(mangaId,r.number(),r.title()==null?"":r.title(),r.fileFormat(),r.pageCount(),r.published(),r.coverUrl(),r.sourceType(),r.sourcePath(),r.unitKind()); return VolumeMapper.toResponse(repo.save(e));} @Transactional public void delete(UUID id,UUID userId,Set<BooksydeRole> roles){var v=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Volume não encontrado.")); books.ensureOwner(books.get(v.getMangaId()),userId,roles); repo.delete(v);} }
